xfs_buf_t* find_or_insert_buffer(struct xfs_buftarg* btp, struct xfs_buf_map* map, int nmaps, xfs_buf_flags_t flags, xfs_buf_t* new_bp) {
    xfs_buf_t* bp = NULL;
    int total_bytes = 0;
    int i;

    if (!btp || !map || nmaps <= 0 || !new_bp) {
        return NULL;
    }

    for (i = 0; i < nmaps; ++i) {
        if (map[i].bm_bn < 0 || map[i].bm_len <= 0) {
            return NULL;
        }
        total_bytes += map[i].bm_len;
    }

    if (total_bytes <= 0) {
        return NULL;
    }

    bp = xfs_buf_find(btp, map, nmaps, flags);

    if (bp) {
        if (xfs_buf_is_stale(bp)) {
            xfs_buf_stale(bp);
        }
        xfs_buf_lock(bp);
        return bp;
    }

    if (flags & XBF_TRYLOCK) {
        return NULL;
    }

    if (new_bp) {
        new_bp->b_maps = map;
        new_bp->b_num_maps = nmaps;
        new_bp->b_flags = flags;
        xfs_buf_insert(new_bp, btp);
        xfs_buf_hold(new_bp);
        xfs_buf_lock(new_bp);
        return new_bp;
    }

    return NULL;
}
